import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game-canvas');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#17212b');
scene.fog=new THREE.Fog('#17212b',18,46);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);
camera.position.set(0,7.2,15.5);camera.lookAt(0,1.1,0);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0xc9d8e9,0x26301f,2));
const keyLight=new THREE.DirectionalLight(0xffd5a5,3.2);keyLight.position.set(-5,10,7);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);scene.add(keyLight);
const rimLight=new THREE.DirectionalLight(0x5ca7db,2.1);rimLight.position.set(7,6,-5);scene.add(rimLight);
const world=new THREE.Group();scene.add(world);let arenaGroup=new THREE.Group();world.add(arenaGroup);
const mats={ground:new THREE.MeshStandardMaterial({color:0x293d36,roughness:.96}),stone:new THREE.MeshStandardMaterial({color:0x626963,roughness:.9}),darkStone:new THREE.MeshStandardMaterial({color:0x3e4947,roughness:.9}),wood:new THREE.MeshStandardMaterial({color:0x4d3023,roughness:.95}),leaf:new THREE.MeshStandardMaterial({color:0x263f36,roughness:.92}),leaf2:new THREE.MeshStandardMaterial({color:0x3e5944,roughness:.92}),gold:new THREE.MeshStandardMaterial({color:0xd9a45b,metalness:.25,roughness:.5}),water:new THREE.MeshStandardMaterial({color:0x293e46,metalness:.25,roughness:.4})};
function mesh(geo,mat,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,r1,r2,h,mat,x,y,z,segments=12){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat,parent,x,y,z)}
function sphere(parent,r,mat,x,y,z,sx=1,sy=1,sz=1){const m=mesh(new THREE.SphereGeometry(r,12,10),mat,parent,x,y,z);m.scale.set(sx,sy,sz);return m}
function makeTree(parent,x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);parent.add(g);cylinder(g,.19,.32,3.5,mats.wood,0,1.75,0,9);for(let i=0;i<5;i++){let y=2.2+i*.33;let leaf=sphere(g,.78-i*.04,i%2?mats.leaf:mats.leaf2,Math.sin(i*2.7)*.32,y,0,1.15,.85,1);leaf.rotation.z=(i%2?.15:-.12)}return g}
function buildWorld(){while(arenaGroup.children.length)arenaGroup.remove(arenaGroup.children[0]);
 const floor=mesh(new THREE.PlaneGeometry(90,90),mats.ground,arenaGroup,0,-.17,0);floor.rotation.x=-Math.PI/2;
 const circle=mesh(new THREE.CylinderGeometry(8,8,.35,64),mats.darkStone,arenaGroup,0,0,0);circle.receiveShadow=true;
 const inner=mesh(new THREE.CylinderGeometry(6.7,6.7,.1,64),mats.stone,arenaGroup,0,.2,0);const center=mesh(new THREE.CylinderGeometry(3.2,3.2,.12,48),new THREE.MeshStandardMaterial({color:0x72766e,roughness:.8}),arenaGroup,0,.27,0);
 for(let r of [4.1,6.15]){let ring=mesh(new THREE.TorusGeometry(r,.035,6,96),mats.gold,arenaGroup,0,.34,0);ring.rotation.x=Math.PI/2}
 for(let i=0;i<24;i++){let a=i/24*Math.PI*2;let x=Math.cos(a)*7.35,z=Math.sin(a)*7.35;let slab=mesh(new THREE.BoxGeometry(.8,.22,.52),i%2?mats.stone:mats.darkStone,arenaGroup,x,.28,z);slab.rotation.y=-a}
 for(let i=0;i<11;i++){let x=-14+i*2.8;makeTree(arenaGroup,x,-9-(i%3)*1.5,.9+(i%3)*.14);if(i%2===0)makeTree(arenaGroup,x+1.4,9,.78)}
 // broken stone pillars, mossy boulders, lanterns and a distant moon
 for(let i=0;i<9;i++){let a=i/9*Math.PI*2;let x=Math.cos(a)*10,z=Math.sin(a)*8.5;let h=1.6+(i%3)*.6;cylinder(arenaGroup,.38,.53,h,mats.darkStone,x,h/2-.05,z,8);cylinder(arenaGroup,.62,.62,.18,mats.stone,x,h,z,8);if(i%3===0){cylinder(arenaGroup,.22,.22,.6,mats.wood,x,h+.37,z,8);sphere(arenaGroup,.21,new THREE.MeshStandardMaterial({color:0xff9b54,emissive:0xf05e22,emissiveIntensity:1.6}),x,h+.75,z)}}
 for(let i=0;i<19;i++){const x=(Math.random()-.5)*17,z=(Math.random()-.5)*16;if(Math.abs(x)<4&&Math.abs(z)<3)continue;let rock=mesh(new THREE.DodecahedronGeometry(.2+Math.random()*.42,0),i%2?mats.darkStone:mats.leaf2,arenaGroup,x,.03,z);rock.scale.y=.5+Math.random()*.6}
 const moonMat=new THREE.MeshBasicMaterial({color:0xf1dfbd});sphere(arenaGroup,1.2,moonMat,8,11,-24,1,1,1);
}
buildWorld();

const characterDefs={naruto:{name:'NARUTO',subtitle:'O NINJA QUE NUNCA DESISTE',desc:'Impulsivo, determinado e movido pela vontade de proteger seus amigos. Um lutador equilibrado que transforma coragem em força.',symbol:'火',colors:{coat:0xe66a2e,pants:0x303f54,wrap:0x283b53,hair:0xe7bd55,skin:0xe8b898,accent:0xe4c488},stats:[['FORÇA',82],['VELOCIDADE',78],['CHAKRA',76]]},sasuke:{name:'SASUKE',subtitle:'O ÚLTIMO HERDEIRO UCHIHA',desc:'Frio e preciso, Sasuke combina velocidade com técnicas de raio. Seus ataques punem qualquer abertura do adversário.',symbol:'雷',colors:{coat:0x334a60,pants:0x263140,wrap:0x824c3b,hair:0x242b3d,skin:0xe5b69a,accent:0xd7d9de},stats:[['FORÇA',78],['VELOCIDADE',88],['CHAKRA',84]}}};
let selected='naruto',player=null,enemy=null,playerRig=null,enemyRig=null,gameState='menu',paused=false,remaining=99,lastTime=0,aiClock=0,attackCooldown=0,playerHealth=100,enemyHealth=100,playerChakra=35,enemyChakra=35,fx=[],effectsOn=true,cameraSpeed=5,soundOn=true;
function makeMat(color,roughness=.8,metalness=0){return new THREE.MeshStandardMaterial({color,roughness,metalness})}
function createFighter(kind,isEnemy=false){const def=characterDefs[kind],c=def.colors,root=new THREE.Group();root.userData.kind=kind;root.position.set(isEnemy?2.45:-2.45,0,0);root.rotation.y=isEnemy?-Math.PI/2:Math.PI/2;arenaGroup.add(root);
