function pauseBattle(title='LUTA PAUSADA',copy='Respire fundo, shinobi.',eyebrow='PAUSA'){paused=true;document.querySelector('#result-title').textContent=title;document.querySelector('#result-copy').textContent=copy;document.querySelector('#result-eyebrow').textContent=eyebrow;document.querySelector('#resume-btn').style.display=title==='LUTA PAUSADA'?'inline-block':'none';document.querySelector('#exit-btn').textContent=title==='LUTA PAUSADA'?'VOLTAR AO MENU':'JOGAR NOVAMENTE';document.querySelector('#battle-overlay').classList.add('show')}
